body:
Hello mrdoob,

Thanks for the great library!   I love Three.js. :)

I just noticed that when adding texts to the CanvasRenderer's canvas, they are flipped upside down.
May be I'm doing something that is not supposed to...Anyhow just wanted to letting you know.

```
<!DOCTYPE html>
<html lang="en">
<head>
<title>Text on Canvas Test</title>
<meta charset="utf-8">
</head>

<body>
<canvas id="regularCanvas" style="left:300px; height:300px; width:300px; background:#FCC"></canvas>
<script src="js/three.min.js"></script><!-- Please set the path -->
<script>
var camera, scene, renderer;

init();
animate();

function init() {           
    camera = new THREE.PerspectiveCamera( 50, window.innerWidth / window.innerHeight, 1, 1000 );
    camera.position.set(0, 0, 0);

    scene = new THREE.Scene();

    renderer = new THREE.CanvasRenderer();
    renderer.setClearColor( 0xccccff );
    renderer.setSize(300, 300);
    renderer.domElement.setAttribute("id", "rendererCanvas");
    document.body.appendChild( renderer.domElement );
}

function animate() {
    //requestAnimationFrame( animate );
    render();
    drawText("regularCanvas", "Text on regular canvas");
    drawText("rendererCanvas", "Text on CanvasRenderer's canvas");
}

function render() {
    renderer.render( scene, camera );
}

function drawText(canvasId, displayText){
    var canvas = document.getElementById(canvasId);
    if (canvas.getContext) {
        ctx = canvas.getContext("2d");
        ctx.font = '12pt Calibri';
        ctx.fillStyle = 'red';
        ctx.textAlign = 'center';
        ctx.fillText(displayText, 100, 100);
    }else{
        console.log("failed getting canvas");
    }
}
</script>
</body>
</html>
```
